import{_ as e,c as n,a0 as s,o as t}from"./chunks/framework.CGHvQLJz.js";const k=JSON.parse('{"title":"テンプレート記法","description":"","frontmatter":{},"headers":[],"relativePath":"template-examples.md","filePath":"template-examples.md"}'),p={name:"template-examples.md"};function o(l,a,i,c,d,r){return t(),n("div",null,a[0]||(a[0]=[s(`<h1 id="テンプレート記法" tabindex="-1">テンプレート記法 <a class="header-anchor" href="#テンプレート記法" aria-label="Permalink to &quot;テンプレート記法&quot;">​</a></h1><p>このページではkinToysのテンプレート記法について解説します。</p><h2 id="記法" tabindex="-1">%記法 <a class="header-anchor" href="#記法" aria-label="Permalink to &quot;%記法&quot;">​</a></h2><p>kinToysでは、kintoneのフィールドを埋め込むテンプレートを実装しています。埋め込みはフィールドコードを指定してください。</p><blockquote><p>%SINGLE_LINE_TEXT%</p></blockquote><p>このように記述することで、<code>SINGLE_LINE_TEXT</code>というフィールドコードを持ったフィールドの値と置換されます。</p><p><strong>フィールド単体の置換</strong></p><p>例えばkintoneアプリに一行文字列フィールドを指定して、そのフィールドコードが<code>SINGLE_LINE_TEXT</code>だった場合に</p><blockquote><p>このフィールドには『%SINGLE_LINE_TEXT%』と記入されています。</p></blockquote><p>というテンプレートを記述したとします。このフィールドに<code>あいうえお</code>と記入してあるとすると、埋込後は以下の文章がクリップボードにコピーされます。</p><blockquote><p>このフィールドには『あいうえお』と記入されています。</p></blockquote><h2 id="ループ記法" tabindex="-1">ループ記法 <a class="header-anchor" href="#ループ記法" aria-label="Permalink to &quot;ループ記法&quot;">​</a></h2><p>kinToysテンプレートはkintoneアプリにあるテーブルを展開できます。ループ記法は<code>%fieldcode{</code>で始まり、<code>}%</code>で終わります。</p><p>例えば、以下のようにテンプレートを記述することでJSONを出力できます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>%table{</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;action&quot;: &quot;%action%&quot;,</span></span>
<span class="line"><span>    &quot;text&quot;: &quot;%text%&quot;</span></span>
<span class="line"><span>  } %joint%</span></span>
<span class="line"><span>}%</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>kinToysは今のところ条件分岐を持ちません。JSONでは繰り返しをカンマで表現しますが、繰り返しの終わりを判定できないため、kintoneアプリ側でカンマの要否を判定するフィールドを作成してください。</p><p>この例では%joint%というkintoneのフィールドにカンマを持たせることで繰り返しの最終要素を記述させました。他にもkintoneが持つ計算式を応用することで柔軟な記述が可能になるかと思います。</p><p>もしkintoneの機能を活用しても「この書き方ができない！」という場面があればご要望ください。</p>`,18)]))}const h=e(p,[["render",o]]);export{k as __pageData,h as default};
